{
  "requirement_definitions": [
    {
      "id": "DMSR-9950",
      "title": "Base to Archive Network Reliability",
      "text": "The Base to Archive communications shall be highly reliable, with MTTR < baseToArchNetMTTR."
    },
    {
      "id": "DMSR-9081",
      "title": "Base to Archive Network Secondary Link",
      "text": "The Base to Archive communications shall provide secondary link or transport mechanism (e.g. protected circuit) for operations support and ”catch up” in the event of extended outage. This secondary link shall be capable of ”bursting” to at least twice the capacity of the primary link."
    },
    {
      "id": "DMSR-5495",
      "title": "Archive Center",
      "text": "The Archive Center shall provide computing, storage, and network infrastructure to support, simultaneously: nightly processing including image processing, detection, association, and moving object pipelines, and the generation of all time-critical data products, i.e. alerts; the data release production, including Level-2 data product creation, permanent storage for all data products (with provenance), including federated Level-3 products; and serve data for replication to data centers and end user sites."
    },
    {
      "id": "DMSR-2087",
      "title": "Archive Center Disaster Recovery",
      "text": "The Archive Center shall provide disaster recovery support preventing loss of LSST data in the case of infrastructure or facility-threatening events. This support shall enable recovery of all LSST archived data from backed up sources, including Data Access Centers."
    },
    {
      "id": "DMSR-3403",
      "title": "Archive Center Co-Location with Existing Facility",
      "text": "The Archive Center shall be hosted at an existing NSF/DOE-funded supercomputing center."
    },
    {
      "id": "DMSR-4835",
      "title": "Archive to Data Access Center Network",
      "text": "The DMS shall provide communications infrastructure between the Archive Center and Data Access Centers suﬃcient to carry scientiﬁc data and associated metadata in support of community and EPO access. Aggregate bandwidth for data transfers from the Archive Center to Data Centers shall be at least archToDacBandwidth."
    },
    {
      "id": "DMSR-5865",
      "title": "Archive to Data Access Center Network Availability",
      "text": "The Archive to Data Access Center communications shall be highly available, with MTBF > archToDacNetMTBF."
    },
    {
      "id": "DMSR-2330",
      "title": "Archive to Data Access Center Network Reliability",
      "text": "The Archive to Data Access Center communications shall be highly reliable, with MTTR < archToDacNetMTTR."
    },
    {
      "id": "DMSR-5282",
      "title": "Archive to Data Access Center Network Secondary Link",
      "text": "The Archive to Data Access Center communications shall provide secondary link or transport mechanism (e.g. protected circuit) for operations support and ”catch up” in the event of extended outage."
    },
    {
      "id": "DMSR-7661",
      "title": "Data Access Centers",
      "text": "The Data Access Centers shall provide computing, storage, and network infrastructure to support open access to LSST data products (with provenance) by end users."
    }
  ],
  "allocation_entries": []
}
